            name = k.slice(1);
            if (name in this.aliases)
                throwParseError(writeDuplicateAliasError(name));
            this.aliases[name] = v;
        }
        else {
            if (name in this.aliases)
                throwParseError(writeDuplicateAliasError(k));
            this.aliases[name] = v;
            this.exportedNames.push(name);
