    this.nodesByHash[rawUnknownUnion.hash] = this.node("intersection", {}, { prereduced: true });
    this.intrinsic =
        $ark.intrinsic ?
            flatMorph($ark.intrinsic, (k, v) => 
            // don't include cyclic aliases from JSON scope
            k.startsWith("json") ? [] : [k, this.bindReference(v)])
